    RAISE EXCEPTION 'Post-condition failed: the finalize overloads are not exactly {p_session_id,p_duration_min} and {p_session_id,p_actual_start,p_actual_end,p_setup_min} with no defaults. Rolling back.';
  END IF;
  IF md5(pg_get_functiondef('public.tg_training_session_lock_guard()'::regprocedure)) IS DISTINCT FROM 'c1af95df40d551b75998cde0a8f290f7'
     OR md5(pg_get_functiondef('public.correct_training_session(uuid, jsonb, uuid[], uuid[], text)'::regprocedure)) IS DISTINCT FROM '8c00066509e9dca338dc3662f55e1211'
     OR md5(pg_get_functiondef('public.finalize_training_session(uuid, integer)'::regprocedure)) IS DISTINCT FROM '3f31142bae70c8fd2001c4fb657f4efa'
     OR md5(pg_get_functiondef('public.attested_training(uuid, timestamp with time zone, timestamp with time zone)'::regprocedure)) IS DISTINCT FROM 'aff25333771cd38c1f473bcde5e1e96e'
     OR md5(pg_get_functiondef('public.dept_iso_hours_for(uuid, timestamp with time zone, timestamp with time zone)'::regprocedure)) IS DISTINCT FROM '705c9a9b5532d28824f5e50e74d6059f' THEN
    RAISE EXCEPTION 'Post-condition failed: the guard / correct / the length-only finalize / attested_training / dept_iso_hours_for changed. Rolling back.';
