-- ---------------------------------------------------------------- state row
SELECT jsonb_build_object(
  'times_finalize_md5', md5(pg_get_functiondef('public.finalize_training_session(uuid, time without time zone, time without time zone, integer)'::regprocedure)),
  'times_finalize_acl', coalesce((SELECT proacl::text FROM pg_proc WHERE oid = 'public.finalize_training_session(uuid, time without time zone, time without time zone, integer)'::regprocedure), ''),
  'length_refusal_gone', NOT ((SELECT prosrc FROM pg_proc WHERE oid = 'public.finalize_training_session(uuid, time without time zone, time without time zone, integer)'::regprocedure) ~ 'already has a length'),
  'times_and_setup_refusals_kept', (SELECT prosrc ~ 'already has actual times' AND prosrc ~ 'already has a setup time' FROM pg_proc WHERE oid = 'public.finalize_training_session(uuid, time without time zone, time without time zone, integer)'::regprocedure),
  'finalize_named_args', (SELECT string_agg(array_to_string(p.proargnames, ',') || ' (defaults ' || p.pronargdefaults || ')', ' | ' ORDER BY p.pronargs) FROM pg_proc p WHERE p.pronamespace = 'public'::regnamespace AND p.proname = 'finalize_training_session'),
  'length_only_finalize_md5', md5(pg_get_functiondef('public.finalize_training_session(uuid, integer)'::regprocedure)), 'guard_md5', md5(pg_get_functiondef('public.tg_training_session_lock_guard()'::regprocedure)), 'correct_md5', md5(pg_get_functiondef('public.correct_training_session(uuid, jsonb, uuid[], uuid[], text)'::regprocedure)),
  'attested_md5', md5(pg_get_functiondef('public.attested_training(uuid, timestamp with time zone, timestamp with time zone)'::regprocedure)), 'iso_md5', md5(pg_get_functiondef('public.dept_iso_hours_for(uuid, timestamp with time zone, timestamp with time zone)'::regprocedure)),
  'fn_count', (SELECT count(*) FROM pg_proc WHERE pronamespace = 'public'::regnamespace AND prokind = 'f'),
  'total_policies', (SELECT count(*) FROM pg_policies WHERE schemaname = 'public'),
  'verified_presence', (SELECT count(*) FROM public.station_presence WHERE verified)
) AS state;
